body:
`mapReportForViewer` now always overwrites `mapped.sections` whenever `mapped.fields` is non-empty. This breaks user-defined layout: sections created/reordered via the new Sections manager (header/text/table order, visibility, etc.) won’t be reflected in the preview because they get replaced by the auto-generated summary/table/chart list. Consider only auto-generating sections when `src.sections` is missing, or merging by updating just the table/chart sections’ columns/config while preserving the existing `src.sections` array/order.
```suggestion
    // Determine if the source schema already defines a custom sections layout.
    const hasUserSections = Array.isArray(src.sections) && src.sections.length > 0;

    // When fields are present, only auto-generate sections if the source
    // schema does not already define its own sections layout. This preserves
    // user-defined ordering, visibility, and section types from the Sections
    // manager while still providing sensible defaults when no sections exist.
    if (mapped.fields && Array.isArray(mapped.fields) && mapped.fields.length > 0) {
      if (!hasUserSections) {
        const hasSummaryFields = mapped.fields.some((f: any) => f.showInSummary || f.aggregation);
        const reportType = mapped.reportType || 'tabular';
        const sections: any[] = [];
        if (reportType === 'summary' || hasSummaryFields) {
          sections.push({ type: 'summary', title: 'Key Metrics' });
        }
        sections.push({
          type: 'table',
          title: 'Details',
          columns: mapped.fields.map((f: any) => ({
            name: f.name,
            label: f.label,
            type: f.type,
            format: f.format,
            renderAs: f.renderAs,
            colorMap: f.colorMap,
          })),
        });
        // Generate chart section from chartConfig if configured
        if (mapped.chartConfig?.chartType) {
          sections.push({
            type: 'chart',
            title: 'Chart',
            chart: {
              type: 'chart',
              chartType: mapped.chartConfig.chartType,
              xAxisField: mapped.chartConfig.xAxisField,
              yAxisFields: mapped.chartConfig.yAxisFields,
            },
          });
        }
        // Preserve any user-defined chart sections from the original schema
        if (Array.isArray(src.sections)) {
          const chartSections = src.sections.filter(
            (s: any) => s.type === 'chart' && !mapped.chartConfig?.chartType,
          );
          sections.push(...chartSections);
        }
        mapped.sections = sections;
      } else {
        // Preserve the existing user-defined sections layout.
        mapped.sections = src.sections;
      }
```
